import{_ as t,o as a,c as i,ae as r}from"./chunks/framework.CSxHcPWC.js";const m=JSON.parse('{"title":"📜 RFC Process","description":"","frontmatter":{},"headers":[],"relativePath":"Management/RFC_PROCESS.md","filePath":"Management/RFC_PROCESS.md"}'),o={name:"Management/RFC_PROCESS.md"};function n(s,e,l,c,h,d){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="📜-rfc-process" tabindex="-1">📜 RFC Process <a class="header-anchor" href="#📜-rfc-process" aria-label="Permalink to &quot;📜 RFC Process&quot;">​</a></h1><p>The <strong>WealthFam RFC (Request for Comments)</strong> process is designed to ensure that major architectural decisions are vetted for forensic accuracy, cross-repository compatibility, and long-term maintainability.</p><hr><h2 id="🚀-when-to-write-an-rfc" tabindex="-1">🚀 When to Write an RFC <a class="header-anchor" href="#🚀-when-to-write-an-rfc" aria-label="Permalink to &quot;🚀 When to Write an RFC&quot;">​</a></h2><p>You MUST write an RFC before starting work on:</p><ul><li><strong>Core Schema Changes</strong>: Modifying primary ledger tables in DuckDB.</li><li><strong>Cross-Service Communication</strong>: Changing how the Parser talks to the Backend.</li><li><strong>New Ingestion Channels</strong>: Implementing IMAP, Plaid, or new file upload logic.</li><li><strong>Breaking API Changes</strong>: Updating public endpoints used by the Mobile App.</li></ul><hr><h2 id="🏗️-the-lifecycle" tabindex="-1">🏗️ The Lifecycle <a class="header-anchor" href="#🏗️-the-lifecycle" aria-label="Permalink to &quot;🏗️ The Lifecycle&quot;">​</a></h2><h3 id="_1-proposal-phase" tabindex="-1">1. Proposal Phase <a class="header-anchor" href="#_1-proposal-phase" aria-label="Permalink to &quot;1. Proposal Phase&quot;">​</a></h3><p>Create a new Markdown file in the <code>Docs/Management/RFCs/</code> folder following the template <code>0000-feature-name.md</code>.</p><ul><li><strong>Summary</strong>: What is the problem?</li><li><strong>Technical Blueprint</strong>: How does it work? (Include Mermaid diagrams).</li><li><strong>Forensic Impact</strong>: How does this affect data integrity and idempotency?</li><li><strong>Unresolved Questions</strong>: What items need team feedback?</li></ul><h3 id="_2-discussion-phase" tabindex="-1">2. Discussion Phase <a class="header-anchor" href="#_2-discussion-phase" aria-label="Permalink to &quot;2. Discussion Phase&quot;">​</a></h3><p>Open a <strong>Pull Request</strong> for the RFC. The Engineering and SRE teams will leave comments focusing on:</p><ul><li>Performance bottlenecks.</li><li>Security vulnerabilities (especially regarding PII in SMS/Email).</li><li>Deployment complexity.</li></ul><h3 id="_3-vetting-phase" tabindex="-1">3. Vetting Phase <a class="header-anchor" href="#_3-vetting-phase" aria-label="Permalink to &quot;3. Vetting Phase&quot;">​</a></h3><p>Once the RFC is approved by at least 2 core members, it is moved to the &quot;Accepted&quot; state. Implementation can begin in the respective repositories.</p><h3 id="_4-implementation-phase" tabindex="-1">4. Implementation Phase <a class="header-anchor" href="#_4-implementation-phase" aria-label="Permalink to &quot;4. Implementation Phase&quot;">​</a></h3><p>All code PRs should reference the RFC number (e.g., <code>Ref: RFC #123</code>).</p><hr><h2 id="🛡️-forensic-review-checklist" tabindex="-1">🛡️ Forensic Review Checklist <a class="header-anchor" href="#🛡️-forensic-review-checklist" aria-label="Permalink to &quot;🛡️ Forensic Review Checklist&quot;">​</a></h2><p>Every RFC must answer:</p><ol><li><strong>Is it Idempotent?</strong> If the server crashes during this operation, can it be safely restarted?</li><li><strong>Is it Verifiable?</strong> How do we audit that the data produced is correct?</li><li><strong>Is it Scalable?</strong> Does this perform well with 10k+ transactions in DuckDB?</li></ol><hr><div align="center"> *Better Decisions · Technical Clarity · Engineering Excellence* </div>',24)])])}const g=t(o,[["render",n]]);export{m as __pageData,g as default};
